import re

def find_literals(text, pattern):
    """
    Searches for the first occurrence of a regex pattern in a given string.

    Args:
        text (str): The string to search within.
        pattern (str): The regex pattern to search for.

    Returns:
        tuple: A tuple containing the matching substring, start index, and end index.
               If no match is found, returns ('', -1, -1).
    """
    # Validate inputs
    if not isinstance(text, str) or not isinstance(pattern, str):
        raise ValueError("Both 'text' and 'pattern' must be strings.")
    if not text or not pattern:
        return ('', -1, -1)

    # Perform regex search
    match = re.search(pattern, text)
    if match:
        return (match.group(), match.start(), match.end())
    else:
        return ('', -1, -1)

# Example usage:
# assert find_literals('The quick brown fox jumps over the lazy dog.', 'fox') == ('fox', 16, 19)
