def div_list(list1, list2):
    # Subproblem 1: Input Handling
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("Both inputs must be lists.")
    if len(list1) != len(list2):
        raise ValueError("Both lists must have the same length.")
    if any(not isinstance(x, (int, float)) for x in list1 + list2):
        raise TypeError("All elements in the lists must be numeric.")
    if any(x == 0 for x in list2):
        raise ValueError("Division by zero is not allowed. The second list contains a zero.")

    # Subproblem 2: Core Algorithm (Element-wise Division)
    result = [a / b for a, b in zip(list1, list2)]

    # Subproblem 4: Final Output
    return result
